'use strict';
let aerospace={missions:[],disciplines:[],groups:[]};
const missionById=id=>aerospace.missions.find(m=>m.id===id);
const bridgeById=id=>learning.bridges.find(b=>b.id===id);
function aeroLinks(ids,type){return ids.map(id=>{const item=type==='lesson'?bridgeById(id):aerospace.disciplines.find(d=>d.id===id);return item?`<a class="aero-chip" href="#${type}/${id}">${esc(item.title||item.name)} ↗</a>`:'';}).join('');}
function aeroDiagram(m){return `<ol class="system-chain" aria-label="Interacting subsystems">${m.subsystems.map((s,i)=>`<li><span>0${i+1}</span>${esc(s)}</li>`).join('')}</ol>`;}
function missionTile(m,i){return `<a class="aero-mission" href="#mission/${m.id}"><div class="aero-orbit" aria-hidden="true"><span>${String(i+1).padStart(2,'0')}</span></div><span class="eyebrow">${esc(m.chain)}</span><h3>${esc(m.title)}</h3><p>${esc(m.summary)}</p><span class="text-link">Open the mission ↗</span></a>`;}
function aeroHome(){return `<section class="section aero-intro"><div class="section-head"><div><span class="eyebrow">AEROSPACE / ONE FOUNDATION, MANY MISSIONS</span><h2>See what the<br><em>work is for.</em></h2></div><p>Begin with a number. Follow it into a machine. Keep the distant possibility connected to something you can understand today.</p></div><div class="aero-choices"><a href="#lesson/arithmetic"><span>01 / START SMALL</span><h3>Before algebra</h3><p>Numbers, fractions, units, and a place to begin.</p></a><a href="#missions"><span>02 / LOOK AHEAD</span><h3>Choose a mission</h3><p>Six paths from fundamentals to aerospace systems.</p></a><a href="#night"><span>03 / WIND DOWN</span><h3>A good story tonight</h3><p>Keep your imagination wide. No homework required.</p></a></div><div class="aero-missions">${aerospace.missions.slice(0,3).map(missionTile).join('')}</div><a href="#missions" class="text-link">Explore all six mission paths →</a></section>`;}
function missionsPage(){return v2head('THE AEROSPACE THREAD / SIX MISSIONS','A reason to learn.<br><em>A world to build.</em>','Choose a question that pulls you forward. Each mission connects physical constraints, engineering disciplines, books, and a small first experiment.')+`<section class="section" style="padding-top:0"><div class="aero-missions">${aerospace.missions.map(missionTile).join('')}</div><div class="aero-banner"><h2>The destination can be extraordinary.<br>The first step can be ordinary.</h2><p>These are learning paths, not professional qualifications or predictions of a future job market.</p><a class="btn small" href="#journey">Start at your level ↗</a> <a class="text-link" href="#specialties">Explore the disciplines →</a></div></section>`;}
function missionPage(id){const m=missionById(id);if(!m)return notFound();const p=learning.projects.find(x=>x.id===m.project);return `<section class="page-head mission-heading"><a class="text-link" href="#missions">← All missions</a><span class="eyebrow">${esc(m.chain)}</span><h1>${esc(m.title)}</h1><p class="lead">${esc(m.summary)}</p>${aeroDiagram(m)}</section><section class="section mission-body"><article><span class="eyebrow">THE CONSTRAINT IS THE INTERESTING PART</span><h2>What has to work?</h2><p class="lead">${esc(m.constraint)}</p><h3>The disciplines come together</h3><div class="aero-chips">${aeroLinks(m.disciplines,'specialty')}</div><h3>What an engineer actually does</h3><p>Define a requirement. Choose a model. Check the interfaces. Measure a result against a prediction. Explain the uncertainty and decide what to test next.</p><h2>From a foundation to a capability.</h2><div class="aero-chips">${aeroLinks(m.bridges,'lesson')}</div><p>Start with the first idea you can explain. Advanced links are previews, not an entrance exam.</p><div class="aero-banner"><span class="eyebrow">BRING IT BACK TO THE BENCH</span><h3>${esc(p.title)}</h3><p>${esc(p.summary)}</p><a class="btn small" href="#project/${p.id}">Open the project ↗</a> <a class="text-link" href="#lab/${m.lab}">Try the connected model →</a></div><h2>Read with a purpose.</h2><p>These books play different roles. Choose an accessible doorway now; keep the technical references for the preparation they require.</p>${aeroBookRows(m.bookIds)}<a class="text-link" href="#path/mission-${m.id}">Open this as a reading route →</a><h2>Keep the horizon honest.</h2><div class="evidence-stack"><article><span class="eyebrow">ESTABLISHED CONTEXT</span><p>${esc(m.today)}</p></article><article><span class="eyebrow">RESEARCH & DEVELOPMENT</span><p>${esc(m.research)}</p></article><article><span class="eyebrow">CONDITIONAL HORIZON</span><p>${esc(m.horizon)}</p></article></div>${ext(m.source)}<p class="note">Research snapshot: ${esc(aerospace.reviewed)}. Mission connections and exercises are editorial synthesis.</p><a class="btn small light" href="#journal">Keep one question in your field notes ↗</a></article><aside class="mission-aside"><span class="eyebrow">YOUR WAY IN</span><h3>One useful idea is enough.</h3><p>You do not need to finish this entire path. Begin at your actual level.</p><a href="#lesson/${m.bridges[0]}" class="btn small">Try the first bridge ↗</a><a href="#lesson/arithmetic" class="text-link">Need an earlier starting point? →</a><a href="#atlas" class="text-link">Return to all 16 fields →</a><a href="#night" class="text-link">Explore fiction tonight →</a></aside></section>`;}
function aeroBookRows(ids){return `<div class="aero-books">${ids.map(id=>index.get(id)).filter(Boolean).map(b=>`<article><span class="badge">${esc(b.stage)} · ${levels[b.difficulty]}</span><h3><button data-open="${b.id}">${esc(b.title)} ↗</button></h3><p>${esc(b.author)}</p><p>${esc(b.why)}</p><button class="save-btn" data-save="${b.id}">${records[b.id]?.status?'✓ Saved':'+ Save'}</button></article>`).join('')}</div>`;}
function specialtiesPage(id){const ds=id?aerospace.disciplines.filter(d=>d.id===id):aerospace.disciplines;if(!ds.length)return notFound();return v2head('AEROSPACE DISCIPLINES / DIRECTIONS TO EXPLORE',id?esc(ds[0].name):'Develop depth.<br><em>Keep the connections.</em>','Aerospace is a collaboration among specialties. Explore the work and its foundations before deciding where to go deeper.')+`<section class="section specialty-grid">${ds.map(d=>`<article class="specialty-card" id="discipline-${d.id}"><span class="eyebrow">${esc(d.id)}</span><h2>${esc(d.name)}</h2><p class="lead">${esc(d.work)}</p><h3>Preparation to grow into</h3><p>${esc(d.preparation)}</p><h3>Try a small version</h3><p>${esc(d.practice)}</p><div class="aero-chips">${aeroLinks(d.bridges,'lesson')}</div><details><summary>Books and connected missions</summary>${aeroBookRows(d.bookIds)}${aerospace.missions.filter(m=>m.disciplines.includes(d.id)).map(m=>`<p><a class="text-link" href="#mission/${m.id}">${esc(m.title)} →</a></p>`).join('')}</details></article>`).join('')}</section><section class="section ground-note"><h2>A direction, not a deadline.</h2><p>Early foundations support several specialties. Engineering for a space mission is distinct from traveling to space; no degree guarantees a crew role. Future hiring and program schedules remain uncertain.</p><a href="#journey" class="text-link">Return to the foundations →</a></section>`;}
function aerospaceJourney(){return v2head('YOUR JOURNEY / FROM FOUNDATIONS TO FLIGHT','The work beneath<br><em>the wonder.</em>','Begin where the ideas become understandable. Preview the horizon without turning it into a deadline.')+`<section class="section journey-start"><div class="aero-banner"><span class="eyebrow">NEW HERE?</span><h2>Start before algebra.</h2><p>A mass budget is addition. An energy share is a fraction. You can begin understanding a physical system before you know its advanced mathematics.</p><a class="btn small" href="#lesson/arithmetic">Try your first bridge ↗</a> <a class="text-link" href="#missions">See where it leads →</a></div></section>${aerospace.groups.map(g=>`<section class="section bridge-group"><div class="section-head"><div><span class="eyebrow">${esc(g.name)}</span><h2>${esc(g.summary)}</h2></div></div><div class="bridge-grid">${g.ids.map(bridgeById).filter(Boolean).map(b=>`<a href="#lesson/${b.id}" class="bridge-card"><span class="eyebrow">${journeyState.practiced.includes(b.id)?'✓ EXPLORED':'OPEN A BRIDGE ↗'}</span><h3>${esc(b.title)}</h3><p>${esc(b.hook)}</p></a>`).join('')}</div></section>`).join('')}<section class="section ground-note"><h2>Learn the subject. Keep the purpose.</h2><p>These ${learning.bridges.length} bridges are conceptual companions to study, not a formal degree plan. Exploring an example is different from mastering a course. Writing, history, biology, and philosophy stay part of a life of building.</p><a href="#specialties" class="text-link">Explore aerospace disciplines →</a><p><a class="text-link" href="#textbooks">Find the advanced textbook companion →</a></p><p>You do not have to make every evening productive. Return to one idea, or simply read a story.</p></section>`;}
function bridgeConnections(b){const ms=aerospace.missions.filter(m=>m.bridges.includes(b.id));return `<div class="bridge-connections">${b.prerequisites?.length?`<h3>An easier doorway</h3><div class="aero-chips">${aeroLinks(b.prerequisites,'lesson')}</div>`:''}${b.misconception?`<h3>A common misunderstanding</h3><p>${esc(b.misconception)}</p>`:''}${ms.length?`<h3>Follow this into a mission</h3>${ms.map(m=>`<p><a class="text-link" href="#mission/${m.id}">${esc(m.title)} →</a></p>`).join('')}`:''}${b.bookIds?.length?`<h3>Reading at different depths</h3>${aeroBookRows(b.bookIds)}`:''}</div>`;}
function bookMissionLinks(id){const ms=aerospace.missions.filter(m=>m.bookIds.includes(id));return ms.length?`<h3>Where this connects</h3><div class="aero-chips">${ms.map(m=>`<a href="#mission/${m.id}" class="aero-chip">${esc(m.title)} →</a>`).join('')}</div>`:'';}
function projectPage(id){const p=learning.projects.find(x=>x.id===id);if(!p)return notFound();return v2head('A SMALL EXPERIMENT / A RECORD YOU CAN EXPLAIN',esc(p.title),esc(p.summary))+`<section class="section lesson-layout"><aside><a class="text-link" href="#projects">← All projects</a></aside><article class="lesson-body"><h2>The question</h2><p>${esc(p.question)}</p><h3>What you need</h3><p>${esc(Array.isArray(p.materials)?p.materials.join(', '):p.materials)}</p><h2>Build the first version</h2><ol>${p.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><h3>What this teaches</h3><p>${esc(p.learn)}</p><h3>Keep the evidence</h3><p>${esc(p.evidence)}</p><h3>One step further</h3><p>${esc(p.stretch)}</p>${ext(p.source)}<p><a class="btn small" href="#journal">Record a result or a question ↗</a></p></article></section>`;}
function expandAeroRoutes(){for(const m of aerospace.missions){if(paths.some(p=>p.id==='mission-'+m.id))continue;paths.push({id:'mission-'+m.id,name:m.title,caption:m.chain,desc:m.summary+' Read an accessible entry now and return to the advanced references with the necessary preparation.',titles:m.bookIds.map(id=>index.get(id)?.title).filter(Boolean),project:learning.projects.find(p=>p.id===m.project).title});}}
// Pure numerical models. The parameters below are teaching assumptions, not flight design inputs.
const AeroMath={
 energy(power,hours,capacity,usable){if(![power,hours,capacity,usable].every(Number.isFinite)||power<=0||hours<0||capacity<0||usable<=0||usable>1)throw Error('Invalid energy inputs');return {used:power*hours,available:capacity*usable,runtime:capacity*usable/power};},
 orbit(altitude){if(!Number.isFinite(altitude)||altitude<160||altitude>36000)throw Error('Altitude outside model');const radius=6378.137+altitude,mu=398600;return {radius,speed:Math.sqrt(mu/radius),period:2*Math.PI*Math.sqrt(radius**3/mu)/60};},
 control(gain,tau){if(!Number.isFinite(gain)||!Number.isFinite(tau)||gain<0||gain>8||tau<=0||tau>10)throw Error('Invalid control inputs');return Array.from({length:81},(_,i)=>{const t=i/4;return {t,y:gain/(1+gain)*(1-Math.exp(-(1+gain)*t/tau))};});}
};
const labDefaults={energy:{power:20,hours:3,capacity:100,usable:80},orbit:{altitude:400},control:{gain:2,tau:4}};
let aeroLab='energy',aeroValues=JSON.parse(JSON.stringify(labDefaults));
function slider(key,label,min,max,step,unit){const v=aeroValues[aeroLab][key];return `<label for="aero-${key}">${label} <output id="value-${key}">${v} ${unit}</output></label><input id="aero-${key}" data-aero-input="${key}" data-unit="${unit}" type="range" min="${min}" max="${max}" step="${step}" value="${v}">`;}
function labNav(){const selected=location.hash.startsWith("#lab/")?location.hash.split("/")[1]:"mechanisms";return `<nav class="model-nav" aria-label="Choose a model"><a href="#workbench" ${["mechanisms","arm","lever"].includes(selected)?'aria-current="page"':''}>Robot & lever</a>${[['energy','Power & energy'],['orbit','Circular orbit'],['control','Feedback']].map(([id,label])=>`<a href="#lab/${id}" ${selected===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;}
function aeroLabPage(id){if(['arm','lever'].includes(id)){labMode=id;return workbenchPage();}if(!labDefaults[id])return notFound();aeroLab=id;const titles={energy:'How long can it work?',orbit:'Higher orbit.<br>Different motion.',control:'A command is only<br>the beginning.'};return v2head('INTERACTIVE WORKBENCH / PREDICT, THEN CHECK',titles[id],'Change one input. Explain the result. Then ask what this model leaves out.')+`<section class="section" style="padding-top:0">${labNav()}<div class="aero-lab"><div id="aero-result">${aeroLabResult()}</div><div class="lab-controls"><h2>Your experiment</h2>${id==='energy'?slider('power','Constant load',5,100,5,'W')+slider('hours','Operating time',1,8,0.5,'h')+slider('capacity','Nominal energy',50,500,10,'Wh')+slider('usable','Usable fraction',10,100,5,'%'):id==='orbit'?slider('altitude','Altitude above equator reference',160,36000,10,'km'):slider('gain','Proportional gain K',0,8,0.25,'')+slider('tau','Plant time constant τ',1,10,0.5,'s')}<button class="btn small light" data-aero-reset>Reset this model</button><h3>Predict first</h3><p>${{energy:'If you double operating time, what happens to energy used? What changes if only the battery gets larger?',orbit:'As circular-orbit radius increases, does speed rise or fall? What happens to period?',control:'Does the output reach the target exactly? Does changing the time constant change the final value?'}[id]}</p><a class="text-link" href="#lesson/${{energy:'energy',orbit:'orbits',control:'feedback'}[id]}">Read the foundation →</a></div></div><a class="text-link" href="#journal">Keep your prediction and what changed →</a></section>`;}
function aeroLabResult(){if(aeroLab==='energy'){const v=aeroValues.energy,r=AeroMath.energy(v.power,v.hours,v.capacity,v.usable/100);return `<span class="eyebrow">ENERGY = POWER × TIME</span><h2>${r.used.toFixed(0)} <small>Wh used</small></h2><div class="energy-track" role="img" aria-label="${r.used} watt-hours requested versus ${r.available} available"><span style="width:${Math.min(100,r.used/r.available*100)}%"></span></div><dl class="model-stats"><div><dt>Available energy</dt><dd>${r.available.toFixed(0)} Wh</dd></div><div><dt>Ideal runtime</dt><dd>${r.runtime.toFixed(2)} h</dd></div><div><dt>Energy remaining</dt><dd>${(r.available-r.used).toFixed(0)} Wh</dd></div></dl><p>${r.used>r.available?'This operating plan exceeds the usable energy. Reduce time or load, or change the supply.':'The plan fits this simplified energy allowance.'}</p><p class="note">Constant load. Usable fraction includes the reserve or limitations you assign. No separate conversion loss, aging, temperature dependence, or peak-current limit is modeled.</p>${ext(aerospace.sources.thermal)}`;}
 if(aeroLab==='orbit'){const v=aeroValues.orbit,r=AeroMath.orbit(v.altitude);return `<span class="eyebrow">IDEAL CIRCULAR EARTH ORBIT</span><svg viewBox="0 0 500 270" class="orbit-picture" role="img" aria-label="Schematic: altitude starts at the surface; orbital radius starts at Earth's center"><circle cx="250" cy="135" r="110" fill="none" stroke="#d9b278"/><circle cx="250" cy="135" r="52" fill="#264e54"/><path d="M250 135H360" stroke="#faf1d6"/><circle cx="360" cy="135" r="7" fill="#d9b278"/><text x="235" y="122" fill="#fff">Earth</text><text x="263" y="158" fill="#fff">radius →</text><text x="190" y="260" fill="#d9b278">SCHEMATIC / NOT TO SCALE</text></svg><dl class="model-stats"><div><dt>Speed</dt><dd>${r.speed.toFixed(3)} km/s</dd></div><div><dt>Period</dt><dd>${r.period.toFixed(1)} min</dd></div><div><dt>Radius from center</dt><dd>${r.radius.toFixed(1)} km</dd></div></dl><p>v = √(μ/r) · T = 2π√(r³/μ). Increasing radius lowers circular speed and lengthens the period.</p><p class="note">Two-body circular orbit; μ = 398600 km³/s²; equatorial reference radius = 6378.137 km. Ignores atmospheric drag, oblateness, other bodies, and maneuvers. Low orbits may decay. Constants: NASA Earth Fact Sheet.</p>${ext({label:'NASA · Earth constants',url:'https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html'})}`;}
 const v=aeroValues.control,pts=AeroMath.control(v.gain,v.tau),last=pts.at(-1);return `<span class="eyebrow">NORMALIZED FIRST-ORDER SYSTEM</span><svg viewBox="0 0 500 280" role="img" aria-label="Response over twenty seconds; final sampled output ${last.y.toFixed(3)}, target 1"><path d="M45 25V235H475" stroke="#a8c6c2" fill="none"/><path d="M45 45H475" stroke="#d9b278" stroke-dasharray="5 5"/><polyline points="${pts.map(p=>`${45+p.t*21},${235-p.y*190}`).join(' ')}" stroke="#8bd3c8" fill="none" stroke-width="3"/><text x="50" y="35" fill="#d9b278">target = 1</text><text x="360" y="265" fill="#fff">time / seconds</text><text x="45" y="255" fill="#fff">0</text><text x="448" y="255" fill="#fff">20</text></svg><dl class="model-stats"><div><dt>Steady output</dt><dd>${(v.gain/(1+v.gain)).toFixed(3)}</dd></div><div><dt>Steady error</dt><dd>${(1/(1+v.gain)).toFixed(3)}</dd></div></dl><p>Plant: τ dy/dt = −y + u. Controller: u = K(1 − y). Starting at zero, the exact response is y(t) = K/(1+K) × [1 − exp(−(1+K)t/τ)].</p><p class="note">No delay, noise, actuator limit, or integral action. This first-order model does not overshoot. Larger gain reduces but does not remove steady error.</p><details><summary>Read the response as a table</summary><table><thead><tr><th>Time (s)</th><th>Output</th></tr></thead><tbody>${pts.filter((_,i)=>i%16===0).map(p=>`<tr><td>${p.t}</td><td>${p.y.toFixed(3)}</td></tr>`).join('')}</tbody></table></details>${ext(aerospace.sources.control)}`;
}
document.addEventListener('input',e=>{const key=e.target.dataset?.aeroInput;if(!key)return;const v=Number(e.target.value);if(!Number.isFinite(v))return;aeroValues[aeroLab][key]=v;document.querySelector('#value-'+key).textContent=v+' '+e.target.dataset.unit;document.querySelector('#aero-result').innerHTML=aeroLabResult();});
document.addEventListener('click',e=>{if(e.target.closest('[data-aero-reset]')){aeroValues[aeroLab]={...labDefaults[aeroLab]};render();}});

function textbooksPage(){return v2head('AEROSPACE TEXTBOOK COMPANION / A SHELF TO GROW INTO','See the subject.<br><em>Prepare for the depth.</em>','Start with a question you can understand. These advanced references become more useful as your mathematics, physics and programming grow.')+`<section class="section" style="padding-top:0"><div class="aero-banner"><h2>Preview now. Study deeply when ready.</h2><p>The 500-book catalog stays intact. This companion adds selected external references, not another completion target. Catalog books keep their existing shelf records; external references open their source pages.</p><p>Course evidence checked ${esc(aerospace.reviewed)}. A teaching-page listing does not establish the textbook for every section or future term. Other recommendations are editorial subject matches.</p><a class="text-link" href="#journey">Return to accessible foundations →</a></div><div class="specialty-grid">${aerospace.textbookGroups.map(g=>`<article class="specialty-card"><span class="eyebrow">ADVANCED REFERENCE / ${esc(g.id)}</span><h2>${esc(g.name)}</h2><h3>Preparation</h3><p>${esc(g.preparation)}</p><a class="text-link" href="#lesson/${g.bridge}">Try the conceptual bridge →</a>${g.refs.map(r=>`<div class="bridge-connections"><h3>${esc(r.title)}</h3><p>${esc(r.author)}<br><span class="badge">${esc(r.edition)}</span></p><p>${esc(r.note)}</p>${r.bookId?`<button class="btn small light" data-open="${r.bookId}">Open catalog record ↗</button> `:''}${ext(r.source)}</div>`).join('')}</article>`).join('')}</div><div class="aero-banner"><h2>Choose an edition with a reason.</h2><p>For a class, use its current syllabus and instructor guidance. For independent study, compare notation, problem numbering, errata and lawful access. A library copy can be enough to explore. No purchase or completion is required.</p><p>The JPL link provides authorized digital chapters. Publisher links may offer descriptions, samples or paid access; they do not imply a free full text.</p></div></section>`;}
